#include <fstream>
#include <iostream>
#include <iterator>
#include "source_studio_loose_collision_asset_candidate.h"
template<class T>static void put(std::ostream&o,const T&v){o.write(reinterpret_cast<const char*>(&v),sizeof(v));}
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"owned x64");if(argc!=5)throw std::runtime_error("mount-list relative-model MDL mesh-output required");std::ifstream f(argv[1]);if(!f)throw std::runtime_error("mount list read");std::vector<std::filesystem::path>mounts;std::string line;while(std::getline(f,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(!line.empty())mounts.emplace_back(line);}const auto mdl=readBinaryAssetCandidate(argv[3]);const auto result=sourceStudioReadLooseCollisionCandidate(argv[2],mounts);const SourceStudioLooseCollisionAssetCandidate asset(mdl,result);std::ofstream out(argv[4],std::ios::binary);if(!out)throw std::runtime_error("owned mesh output");size_t convexes=0,triangles=0;uint16_t solids=0;if(asset.sharedShape()){const SourcePhyCompactGeometryCandidate geometry(result.bytes);if(geometry.solids.size()>65535)throw std::runtime_error("owned solid count");solids=uint16_t(geometry.solids.size());put(out,solids);for(const auto&solid:geometry.solids){put(out,uint32_t(solid.size()));convexes+=solid.size();for(const auto&convex:solid){put(out,convex.gameData);put(out,uint32_t(convex.triangles.size()));triangles+=convex.triangles.size();for(const auto&t:convex.triangles)put(out,t);}}}else put(out,solids);out.flush();if(!out)throw std::runtime_error("owned mesh flush");std::cout<<"{\"status\":\"PASS\",\"loaded_solids\":"<<solids<<",\"convexes\":"<<convexes<<",\"triangles\":"<<triangles<<",\"known_missing_in_configured_loose_mounts\":"<<asset.missingInConfiguredLooseMounts()<<"}\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
